<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient(),schools=ref<any[]>([]),sports=ref<any[]>([]),rows=ref<any[]>([]),name=ref(''),schoolId=ref(''),sportId=ref(''),year=ref(new Date().getFullYear()),type=ref('intra_school'),mode=ref('central'),date=ref(''),error=ref(''),success=ref('')
async function load(){const [s,sp,c]=await Promise.all([db.from('schools').select('id,name').order('name'),db.from('sports').select('id,name').order('name'),db.from('competitions').select('id,name,competition_type,management_mode,status,school_year').order('created_at',{ascending:false})]);schools.value=s.data||[];sports.value=sp.data||[];rows.value=c.data||[];if(!schoolId.value&&schools.value.length)schoolId.value=schools.value[0].id;if(!sportId.value&&sports.value.length)sportId.value=sports.value[0].id;error.value=s.error?.message||sp.error?.message||c.error?.message||''}
onMounted(load)
async function add(){error.value='';success.value='';const r=await db.from('competitions').insert({name:name.value.trim(),sport_id:sportId.value||null,competition_type:type.value,management_mode:mode.value,organiser_school_id:schoolId.value||null,school_year:year.value,starts_on:date.value||null,status:'draft'}).select('id').single();if(r.error){error.value=r.error.message;return}const p=await db.from('competition_schools').insert({competition_id:r.data.id,school_id:schoolId.value});if(p.error)error.value='Competition created, but participating school could not be added: '+p.error.message;else success.value='Competition created';name.value='';await load()}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>Competitions</h1><p>Create intra-school or inter-school competitions with central, school or hybrid management.</p><form class="card editor" @submit.prevent="add"><label>Competition name<input v-model="name" required></label><label>Sport<select v-model="sportId" required><option v-for="s in sports" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Organising school<select v-model="schoolId" required><option v-for="s in schools" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Type<select v-model="type"><option value="intra_school">Intra-School</option><option value="inter_school">Inter-School</option></select></label><label>Management<select v-model="mode"><option value="central">Central</option><option value="school">School Managed</option><option value="hybrid">Hybrid</option></select></label><label>School year<input v-model.number="year" type="number" min="2000" max="2200" required></label><label>Start date<input v-model="date" type="date"></label><button class="btn">Create Competition</button></form><p v-if="error" class="error">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="card"><h2>Competitions</h2><div v-for="c in rows" :key="c.id" class="data-row"><span>{{c.name}} ({{c.school_year}})</span><small>{{c.competition_type}} · {{c.management_mode}} · {{c.status}}</small></div></div></div></div></template>
